//! Tests for the temporary launcher's directories, isolation and settings.
//!
//! Split from `with_command.rs` to keep that file within the repository's
//! 1000-line limit.

/// Gemini CLI resolves settings as `<home>/.gemini/settings.json`, where
/// `<home>` is `GEMINI_CLI_HOME` if set and `$HOME` otherwise. Pointing
/// `GEMINI_CLI_HOME` at the `.gemini` directory made it look one level too
/// deep, fall back to the user's personal settings, and refuse the run
/// (issue #227). Both variables must therefore name the root.

#[test]
fn the_gemini_client_is_pointed_at_the_isolated_home() {
    let root = tempfile::tempdir().expect("isolated root");
    let manager = ClientManager::isolated(root.path());
    let mut command = Command::new("gemini");
    configure_isolation(
        &mut command,
        &manager,
        root.path(),
        ClientKind::GeminiCli,
        true,
    )
    .expect("configure gemini isolation");

    let environment: std::collections::HashMap<_, _> = command
        .get_envs()
        .filter_map(|(key, value)| Some((key.to_string_lossy().into_owned(), value?)))
        .collect();

    for name in ["HOME", "GEMINI_CLI_HOME"] {
        assert_eq!(
            environment.get(name).map(|value| value.to_string_lossy()),
            Some(root.path().to_string_lossy()),
            "{name} must name the isolated root, not the .gemini directory \
             inside it — the CLI appends `.gemini` itself"
        );
    }
    // The file the CLI actually reads lives under that home.
    assert_eq!(
        manager.config_path(ClientKind::GeminiCli),
        root.path().join(".gemini/settings.json")
    );
    // The trusted-directory prompt cannot be answered non-interactively.
    assert_eq!(
        environment
            .get("GEMINI_CLI_TRUST_WORKSPACE")
            .map(|value| value.to_string_lossy()),
        Some(std::borrow::Cow::Borrowed("true"))
    );
}

/// End to end: after preparing the client, the file Gemini CLI actually
/// reads must exist and select the API-key flow. The router previously
/// wrote a correct file the CLI never opened (issue #227).
/// A default Claude launch lives in a persistent Router-owned profile. The
/// Router must not synthesize a settings file there: Claude owns the profile
/// contents, while routing stays process-local (issue #536).

#[test]
fn default_claude_launch_uses_an_empty_persistent_router_profile() {
    let profiles = tempfile::tempdir().expect("profile root");
    let models = [RouterModel {
        id: "test-model".to_string(),
        owned_by: "test".to_string(),
        ..RouterModel::default()
    }];
    let extended = TemporaryClient::prepare(&Preparation {
        client: ClientKind::ClaudeCode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare with the default configuration handling");
    let names: Vec<String> = extended
        .command
        .get_envs()
        .map(|(name, _)| name.to_string_lossy().into_owned())
        .collect();
    let config_dir = extended
        .command
        .get_envs()
        .find_map(|(name, value)| (name == "CLAUDE_CONFIG_DIR").then_some(value?))
        .expect("default Claude launch must set CLAUDE_CONFIG_DIR");
    let expected = profiles
        .path()
        .join("link-assistant-router/clients/claude/home");
    assert_eq!(Path::new(config_dir), expected);
    assert_eq!(
        fs::read_dir(&expected)
            .expect("read Router-owned Claude profile")
            .count(),
        0,
        "Router must create only the empty profile and let Claude populate it"
    );
    // The router's actual contribution is still applied.
    for required in ["ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL"] {
        assert!(
            names.iter().any(|name| name == required),
            "{required} missing: {names:?}"
        );
    }
    let environment = extended
        .command
        .get_envs()
        .filter_map(|(name, value)| {
            Some((
                name.to_string_lossy().into_owned(),
                value?.to_string_lossy().into_owned(),
            ))
        })
        .collect::<std::collections::HashMap<_, _>>();
    assert_eq!(
        environment.get("ANTHROPIC_BASE_URL").map(String::as_str),
        Some("http://router.test/api/services/anthropic")
    );
    assert_eq!(
        environment
            .get("CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY")
            .map(String::as_str),
        Some("1")
    );
    assert!(
        !names
            .iter()
            .any(|name| name == "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC"),
        "the run must inherit the user's setting instead of installing the presence-based disable switch"
    );
    assert_eq!(
        environment.get("ANTHROPIC_API_KEY").map(String::as_str),
        Some("")
    );
    for untouched in [
        "ANTHROPIC_MODEL",
        "ANTHROPIC_DEFAULT_OPUS_MODEL",
        "ANTHROPIC_DEFAULT_SONNET_MODEL",
        "ANTHROPIC_DEFAULT_HAIKU_MODEL",
        "CLAUDE_CODE_SUBAGENT_MODEL",
    ] {
        assert!(!environment.contains_key(untouched), "{untouched}");
    }

    // Asking for isolation still repoints the directory.
    let isolated = TemporaryClient::prepare(&Preparation {
        client: ClientKind::ClaudeCode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: true,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: None,
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare isolated");
    assert!(
        isolated
            .command
            .get_envs()
            .any(|(name, _)| name == "CLAUDE_CONFIG_DIR"),
        "--isolated-config must still give the client its own directory"
    );
}

/// A z.ai-only launch pins the main/subagent pair and the families Claude's
/// Default row resolves through, all to one authorized model: an unpinned
/// family describes Default as an unauthorized Opus (issue #630).

#[test]
fn zai_only_claude_launch_pins_main_subagent_and_default_row() {
    let profiles = tempfile::tempdir().expect("profile root");
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "future-first-2099", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-explicit-2099", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}}
    ]))
    .expect("deserialize profiled z.ai models");
    let resumed = TemporaryClient::prepare(&Preparation {
        client: ClientKind::ClaudeCode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: false,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare a resumed z.ai-only Claude session");
    let resumed_env = resumed
        .command
        .get_envs()
        .filter_map(|(key, value)| {
            Some((
                key.to_string_lossy().into_owned(),
                value?.to_string_lossy().into_owned(),
            ))
        })
        .collect::<std::collections::HashMap<_, _>>();
    for key in crate::clients::CLAUDE_GATEWAY_TARGET_ENV {
        assert_eq!(
            resumed_env.get(key).map(String::as_str),
            Some("future-first-2099"),
            "{key}"
        );
    }
    for key in crate::clients::CLAUDE_DEFAULT_ROW_ENV {
        assert_eq!(
            resumed_env.get(key).map(String::as_str),
            Some("future-first-2099"),
            "{key}"
        );
    }

    let explicit = TemporaryClient::prepare(&Preparation {
        client: ClientKind::ClaudeCode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: Some("future-explicit-2099"),
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare an explicit z.ai Claude model");
    let explicit_env = explicit
        .command
        .get_envs()
        .filter_map(|(key, value)| {
            Some((
                key.to_string_lossy().into_owned(),
                value?.to_string_lossy().into_owned(),
            ))
        })
        .collect::<std::collections::HashMap<_, _>>();
    for key in crate::clients::CLAUDE_GATEWAY_TARGET_ENV {
        assert_eq!(
            explicit_env.get(key).map(String::as_str),
            Some("future-explicit-2099"),
            "explicit model must win for {key}"
        );
    }
    for key in crate::clients::CLAUDE_DEFAULT_ROW_ENV {
        assert_eq!(
            explicit_env.get(key).map(String::as_str),
            Some("future-explicit-2099"),
            "Default row must follow the explicit model for {key}"
        );
    }
}

/// Claude filters exact non-Anthropic gateway IDs out of `/model`. Router
/// lists every authorized exact row through Claude's supported process-local
/// `--settings` surface, without aliases or duplicates (#419), Anthropic's own
/// exact IDs included when Anthropic is authorized (#621).

#[test]
fn claude_picker_adds_each_filtered_authorized_model_exactly_once() {
    let profiles = tempfile::tempdir().expect("profile root");
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "future-native-id", "owned_by": "anthropic"},
        {"id": "future-claude-shaped-zai", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-glm-beta", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-glm-alpha", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-glm-alpha", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "sonnet", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}}
    ]))
    .expect("deserialize client capability fixture");
    let prepared = TemporaryClient::prepare(&Preparation {
        client: ClientKind::ClaudeCode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: false,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare mixed Claude catalog");
    let arguments = prepared
        .command
        .get_args()
        .map(|argument| argument.to_string_lossy().into_owned())
        .collect::<Vec<_>>();
    let settings = arguments
        .windows(2)
        .find_map(|pair| (pair[0] == "--settings").then_some(&pair[1]))
        .expect("Router must provide a process-local model picker");
    let settings: serde_json::Value = serde_json::from_str(settings).expect("valid settings JSON");
    assert_eq!(
        settings,
        json!({
            // The presentation default that keeps a completed thinking trace on
            // screen travels beside the picker rows, in the same process-local
            // settings, so neither profile is rewritten (issue #560).
            "verbose": true,
            "modelPicker": {
                "options": [
                    {"model": "future-native-id", "label": "future-native-id"},
                    {"model": "future-claude-shaped-zai", "label": "future-claude-shaped-zai", "behavesAs": "claude-sonnet-5"},
                    {"model": "future-glm-alpha", "label": "future-glm-alpha", "behavesAs": "claude-sonnet-5"},
                    {"model": "future-glm-beta", "label": "future-glm-beta", "behavesAs": "claude-sonnet-5"}
                ],
                "replaceBuiltInOptions": false
            }
        })
    );
}

/// Issues #620 and #621: a live z.ai row carries no Claude capability
/// metadata, and Claude Code accepts a `{label, model}` picker row without
/// `behavesAs`. Requiring the metadata refused every z.ai-only launch, even an
/// explicit `--model`. The row is listed as it is, and nothing is invented.

#[test]
fn claude_picker_lists_rows_without_capability_metadata() {
    // The exact row a released z.ai Coding Plan deployment serves.
    let models = crate::clients::parse_router_models(&[
        json!({
            "id": "glm-5.3",
            "object": "model",
            "owned_by": "z.ai",
            "selector_kind": "provider_advertised_exact_id",
            "capability_provenance": {"fields": {}},
            "router_protocols": ["anthropic"]
        }),
        json!({
            "id": "glm-5.3-flash",
            "object": "model",
            "owned_by": "z.ai",
            "selector_kind": "provider_advertised_exact_id",
            "capability_provenance": {"fields": {}},
            "router_protocols": ["anthropic"]
        }),
    ])
    .expect("the released z.ai row parses");
    assert_eq!(
        models[0].selector_kind,
        crate::model_contract::ModelSelectorKind::Concrete
    );
    let settings = prepared_claude_settings(&models);
    assert_eq!(
        settings["modelPicker"],
        json!({
            "options": [
                {"label": "glm-5.3", "model": "glm-5.3"},
                {"label": "glm-5.3-flash", "model": "glm-5.3-flash"}
            ],
            "replaceBuiltInOptions": true
        })
    );

    // Rows that disagree about one exact ID are no evidence of either value:
    // one picker row, and no `behavesAs` on it.
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "future-conflict", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-conflict", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-haiku-4-5", "source": "provider-protocol:z.ai-anthropic"}}},
        {"id": "future-incomplete", "owned_by": "z.ai", "client_capabilities": {"claude": {"behaves_as": "claude-sonnet-5", "source": " "}}}
    ]))
    .expect("deserialize conflicting capability fixture");
    assert_eq!(
        prepared_claude_settings(&models)["modelPicker"]["options"],
        json!([
            {"label": "future-conflict", "model": "future-conflict"},
            {"label": "future-incomplete", "model": "future-incomplete"}
        ])
    );
}

/// Issue #379: Codex supports repeatable global `-c` overlays, so routing does
/// not require replacing `HOME` or `CODEX_HOME`. The overlay must precede the
/// user's subcommand and arguments; `launch` appends those after preparation.

#[test]
fn codex_overlays_routing_without_repointing_user_configuration() {
    let models = [RouterModel {
        router_unavailable_reason: None,
        id: "gpt-5.6-sol".to_string(),
        owned_by: "codex".to_string(),
        selector_kind: crate::model_contract::ModelSelectorKind::default(),
        capability_provenance: serde_json::Value::Null,
        default_reasoning_level: Some("high".to_string()),
        supported_reasoning_levels: Some(vec![crate::clients::RouterReasoningLevel {
            effort: "high".to_string(),
            description: "Deep reasoning".to_string(),
        }]),
        provider_created_at: None,
        client_capabilities: crate::clients::RouterClientCapabilities::default(),
    }];
    assert!(
        extends_user_configuration(ClientKind::Codex, false, false),
        "ordinary Codex runs can layer routing through CLI configuration"
    );
    assert!(
        !extends_user_configuration(ClientKind::Codex, true, false),
        "explicit isolation must still replace the client configuration"
    );

    let prepared = TemporaryClient::prepare(&Preparation {
        client: ClientKind::Codex,
        base_url: "http://router.test/path?tenant=one",
        token: "la_sk_header.payload.sig",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: None,
        codex_reasoning_effort: None,
        codex_backend_base_url: Some("http://127.0.0.1:43123/api/services/codex/backend-api"),
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare Codex overlay");

    let environment = prepared
        .command
        .get_envs()
        .map(|(name, value)| (name.to_string_lossy().into_owned(), value))
        .collect::<std::collections::HashMap<_, _>>();
    assert!(!environment.contains_key("HOME"), "{environment:?}");
    assert!(!environment.contains_key("CODEX_HOME"), "{environment:?}");
    assert_eq!(
        environment
            .get("LINK_ASSISTANT_TOKEN")
            .and_then(|value| *value)
            .map(|value| value.to_string_lossy()),
        Some(std::borrow::Cow::Borrowed("la_sk_header.payload.sig"))
    );
    assert_eq!(
        environment
            .get("CODEX_ACCESS_TOKEN")
            .and_then(|value| *value)
            .map(|value| value.to_string_lossy()),
        Some(std::borrow::Cow::Borrowed("at-header.payload.sig"))
    );
    assert_eq!(
        environment
            .get("CODEX_CONNECTORS_TOKEN")
            .and_then(|value| *value)
            .map(|value| value.to_string_lossy()),
        Some(std::borrow::Cow::Borrowed("at-header.payload.sig"))
    );
    assert_eq!(
        environment
            .get("CODEX_AUTHAPI_BASE_URL")
            .and_then(|value| *value)
            .map(|value| value.to_string_lossy()),
        Some(std::borrow::Cow::Borrowed(
            "http://router.test/path?tenant=one/api/services/codex"
        ))
    );

    let arguments = prepared
        .command
        .get_args()
        .map(|argument| argument.to_string_lossy().into_owned())
        .collect::<Vec<_>>();
    assert_eq!(arguments[0], "-c");
    let provider = arguments[1]
        .strip_prefix("model_provider=")
        .and_then(|value| serde_json::from_str::<String>(value).ok())
        .expect("process-local model provider argument");
    assert!(provider.starts_with("link-assistant-run-"), "{provider}");
    assert_eq!(arguments[2], "-c");
    let catalog_path = arguments[3]
        .strip_prefix("model_catalog_json=")
        .and_then(|value| serde_json::from_str::<String>(value).ok())
        .expect("process-local model catalog argument");
    assert!(Path::new(&catalog_path).starts_with(prepared.directory.path()));
    let catalog: serde_json::Value = serde_json::from_slice(
        &std::fs::read(&catalog_path).expect("read process-local model catalog"),
    )
    .expect("parse process-local model catalog");
    assert_eq!(catalog["models"][0]["slug"], "gpt-5.6-sol");
    assert_eq!(catalog["models"][0]["default_reasoning_level"], "high");
    assert_eq!(
        catalog["models"][0]["supported_reasoning_levels"],
        json!([{"effort": "high", "description": "Deep reasoning"}])
    );
    assert_eq!(catalog["models"].as_array().unwrap().len(), 1);
    assert_eq!(arguments[4], "-c");
    assert_eq!(
        arguments[5],
        format!(
            "model_providers.{provider}={{ name = \"OpenAI\", base_url = \"http://router.test/path?tenant=one/api/services/codex/v1\", wire_api = \"responses\", requires_openai_auth = true, supports_websockets = true, supports_standalone_web_search = true }}"
        )
    );
    assert!(!arguments[5].contains("env_key"));
    assert_eq!(
        arguments[6..],
        [
            "-c",
            "chatgpt_base_url=\"http://127.0.0.1:43123/api/services/codex/backend-api\"",
            "-c",
            "experimental_realtime_ws_base_url=\"http://router.test/path?tenant=one/api/services/codex/v1\"",
            "-c",
            "experimental_realtime_webrtc_call_base_url=\"http://router.test/path?tenant=one/api/services/codex/v1\"",
        ]
    );

    let isolated = TemporaryClient::prepare(&Preparation {
        client: ClientKind::Codex,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: true,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: None,
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare isolated Codex");
    let isolated_home = isolated
        .command
        .get_envs()
        .find_map(|(name, value)| (name == "HOME").then_some(value?))
        .expect("isolated Codex sets HOME");
    assert_eq!(Path::new(isolated_home), isolated.directory.path());
    assert!(
        isolated
            .command
            .get_envs()
            .any(|(name, value)| name == "CODEX_HOME" && value.is_none()),
        "isolation must prevent an inherited CODEX_HOME from escaping"
    );
    assert!(isolated.command.get_args().next().is_none());
    assert!(
        isolated
            .directory
            .path()
            .join(".codex/config.toml")
            .is_file()
    );
}

/// A client configured through a file is isolated even though extending is
/// the default, because there is nothing to layer short of rewriting that
/// file.
///
/// A fallback rather than an error: the user did not ask for isolation, they
/// asked to run a client, and this is the only way it can be run. Refusing
/// was right while extending was opt-in — the flag could not be honoured —
/// but as a default it would make `with opencode` fail outright (issue
/// #277).

#[test]
fn a_file_configured_client_is_isolated_even_by_default() {
    let models = [RouterModel {
        id: "test-model".to_string(),
        owned_by: "test".to_string(),
        selector_kind: crate::model_contract::ModelSelectorKind::default(),
        capability_provenance: serde_json::Value::Null,
        ..RouterModel::default()
    }];
    assert!(
        !extends_user_configuration(ClientKind::Opencode, false, false),
        "opencode sets no base-url variable, so there is nothing to layer"
    );
    assert!(
        !extends_user_configuration(ClientKind::ClaudeCode, false, false),
        "Claude defaults to its persistent Router-owned profile"
    );
    assert!(
        extends_user_configuration(ClientKind::ClaudeCode, false, true),
        "--extend-global-config explicitly opts into the real Claude profile"
    );
    assert!(
        !extends_user_configuration(ClientKind::ClaudeCode, true, true),
        "--isolated-config wins over the default"
    );

    // And it still prepares rather than failing.
    let profiles = tempfile::tempdir().expect("profile root");
    TemporaryClient::prepare(&Preparation {
        client: ClientKind::Opencode,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("a file-configured client must still run");
}

/// Gemini CLI sets both connection variables and still cannot be extended.
///
/// It is pointed at the router by a `settings.json` it resolves from `HOME`,
/// so extending — which leaves `HOME` alone — would write that file where
/// the client never looks and let the user's own settings decide the run
/// (issue #227). Having both variables is therefore not enough to layer
/// onto, and the default must not assume it is.

#[test]
fn a_client_needing_a_written_file_is_isolated_despite_its_variables() {
    let integration = ClientKind::GeminiCli.integration();
    assert!(
        integration.token_env.is_some() && integration.base_url_env.is_some(),
        "the variables alone would otherwise qualify it for extending"
    );
    assert!(
        !extends_user_configuration(ClientKind::GeminiCli, false, false),
        "routing depends on a file only isolation makes reachable"
    );
}

#[test]
fn a_prepared_gemini_run_leaves_settings_where_the_cli_reads_them() {
    let models = [RouterModel {
        id: "test-model".to_string(),
        owned_by: "test".to_string(),
        ..RouterModel::default()
    }];
    let profiles = tempfile::tempdir().expect("profile root");
    let temporary = TemporaryClient::prepare(&Preparation {
        client: ClientKind::GeminiCli,
        base_url: "http://router.test",
        token: "task-token",
        model_override: None,
        models: &models,
        isolated_config: false,
        extend_user_configuration: false,
        one_shot: true,
        user_model_selection: None,
        profile_root: Some(profiles.path()),
        codex_reasoning_effort: None,
        codex_backend_base_url: None,
        ca_cert: None,
        user_claude_settings: None,
    })
    .expect("prepare gemini");
    let root = temporary.directory.path();
    let home = temporary
        .command
        .get_envs()
        .find_map(|(name, value)| (name == "HOME").then_some(value?))
        .expect("gemini run sets HOME");
    // The CLI resolves its settings from HOME; the file must be there.
    let settings = Path::new(home).join(".gemini/settings.json");
    assert!(
        settings.is_file(),
        "no settings at {}, which is where the CLI looks",
        settings.display()
    );
    let written = fs::read_to_string(&settings).expect("read settings");
    assert!(written.contains("gemini-api-key"), "{written}");
    assert!(Path::new(home).starts_with(root), "HOME escaped the root");
}

/// An isolated run must be governed by the settings the router wrote. The
/// previous `create_new` silently deferred to whatever was already there,
/// which with the `HOME` fix would let an inherited `oauth-personal`
/// survive and fail the run.

#[test]
fn written_gemini_settings_replace_an_existing_file() {
    let root = tempfile::tempdir().expect("isolated root");
    let path = root.path().join(".gemini/settings.json");
    fs::create_dir_all(path.parent().expect("parent")).expect("create directory");
    fs::write(
        &path,
        r#"{"security":{"auth":{"selectedType":"oauth-personal"}}}"#,
    )
    .expect("seed a conflicting file");

    write_gemini_settings(&path).expect("write settings");

    let written = fs::read_to_string(&path).expect("read settings");
    assert!(written.contains("gemini-api-key"), "{written}");
    assert!(
        !written.contains("oauth-personal"),
        "the inherited value survived: {written}"
    );
}

#[test]
fn gemini_settings_select_the_api_key_flow() {
    let root = tempfile::tempdir().expect("isolated root");
    let path = root.path().join(".gemini/settings.json");
    write_gemini_settings(&path).expect("write settings");
    let written: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(&path).expect("read")).expect("valid JSON");
    assert_eq!(
        written["security"]["auth"]["selectedType"],
        "gemini-api-key"
    );
}

/// Every client prepares under a root the router owns, and only the ones
/// that were meant to be thrown away are.
///
/// A client routed through a file the router writes *lives* in that
/// directory. Discarding it after every run made every launch a first
/// launch — no session history, so nothing to resume, and onboarding
/// answered again from scratch (issue #298).

#[test]
fn a_client_that_cannot_be_extended_keeps_its_profile() {
    let models = [RouterModel {
        router_unavailable_reason: None,
        id: "test-model".to_string(),
        owned_by: "test".to_string(),
        selector_kind: crate::model_contract::ModelSelectorKind::default(),
        capability_provenance: serde_json::Value::Null,
        default_reasoning_level: Some("medium".to_string()),
        supported_reasoning_levels: Some(vec![crate::clients::RouterReasoningLevel {
            effort: "medium".to_string(),
            description: "Test reasoning".to_string(),
        }]),
        provider_created_at: None,
        client_capabilities: crate::clients::RouterClientCapabilities::default(),
    }];
    let profiles = tempfile::tempdir().expect("profile root");
    for client in ClientKind::ALL {
        if client == ClientKind::Cursor {
            assert!(
                TemporaryClient::prepare(&Preparation {
                    client,
                    base_url: "http://router.test",
                    token: "task-token",
                    model_override: None,
                    models: &models,
                    isolated_config: false,
                    extend_user_configuration: false,
                    one_shot: true,
                    user_model_selection: None,
                    profile_root: Some(profiles.path()),
                    codex_reasoning_effort: None,
                    codex_backend_base_url: None,
                    ca_cert: None,
                    user_claude_settings: None,
                })
                .is_err()
            );
            continue;
        }
        let temporary = TemporaryClient::prepare(&Preparation {
            client,
            base_url: "http://router.test",
            token: "task-token",
            model_override: None,
            models: &models,
            isolated_config: false,
            extend_user_configuration: false,
            one_shot: true,
            user_model_selection: None,
            profile_root: Some(profiles.path()),
            codex_reasoning_effort: None,
            codex_backend_base_url: None,
            ca_cert: None,
            user_claude_settings: None,
        })
        .unwrap_or_else(|error| panic!("{client} failed setup: {error}"));
        let root = temporary.directory.path().to_path_buf();
        assert_eq!(temporary.command.get_program(), client.command());
        let environment = temporary
            .command
            .get_envs()
            .filter_map(|(name, value)| value.map(|value| (name, value)))
            .collect::<std::collections::HashMap<_, _>>();
        if let Some(token_env) = client.token_env() {
            assert_eq!(
                environment.get(std::ffi::OsStr::new(token_env)).copied(),
                Some(std::ffi::OsStr::new("task-token")),
                "{client} did not receive its token environment"
            );
        }
        for name in [
            "HOME",
            "CLAUDE_CONFIG_DIR",
            "GEMINI_CLI_HOME",
            "OPENCODE_CONFIG",
            "OPENCODE_CONFIG_DIR",
        ] {
            if let Some(value) = environment.get(std::ffi::OsStr::new(name)) {
                assert!(
                    Path::new(value).starts_with(&root),
                    "{client} {name} escaped its root"
                );
            }
        }
        let keeps_a_profile = !extends_user_configuration(client, false, false);
        drop(temporary);
        assert_eq!(
            root.exists(),
            keeps_a_profile,
            "{client}: a client routed through a written file must keep its profile, and \
             one that only needs two environment variables must not leave a directory behind"
        );
        if keeps_a_profile {
            assert!(
                root.starts_with(profiles.path()),
                "{client} profile must live under the router's own directory, not TMPDIR: \
                 {}",
                root.display()
            );
        }
    }
}

/// Issue #657: an exhausted z.ai plan keeps its rows listed, so a saved or
/// requested GLM model is still accepted, but the picker and the launch say
/// Router cannot serve it right now and name a servable alternative.

#[test]
fn an_unservable_claude_model_is_labelled_and_warned_about() {
    let reason = "z.ai Coding Plan cannot serve requests (code 1113): Insufficient balance";
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "claude-sonnet-5-5", "owned_by": "anthropic"},
        {"id": "glm-5.3", "owned_by": "z.ai", "router_unavailable_reason": reason}
    ]))
    .expect("deserialize exhausted catalog fixture");
    let options = prepared_claude_settings(&models)["modelPicker"]["options"].clone();
    assert!(
        options
            .as_array()
            .unwrap()
            .contains(&json!({"label": "glm-5.3 (unavailable)", "model": "glm-5.3"})),
        "{options}"
    );

    let warning = claude_unavailable_model_warning(Some("glm-5.3"), &models, None)
        .expect("an unservable saved model is reported");
    assert!(warning.contains("`glm-5.3`"), "{warning}");
    assert!(warning.contains(reason), "{warning}");
    assert!(warning.contains("`claude-sonnet-5-5`"), "{warning}");
    assert_eq!(
        claude_unavailable_model_warning(Some("claude-sonnet-5-5"), &models, None),
        None
    );
    assert_eq!(claude_unavailable_model_warning(None, &models, None), None);
}

#[test]
fn the_unavailable_model_warning_suggests_the_flagship() {
    let reason = "z.ai Coding Plan cannot serve requests (code 1113)";
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "claude-haiku-4-5", "owned_by": "anthropic"},
        {"id": "claude-opus-4-20250514", "owned_by": "anthropic"},
        {"id": "claude-opus-4-1", "owned_by": "anthropic"},
        {"id": "claude-sonnet-5-5", "owned_by": "anthropic"},
        {"id": "claude-opus-5-5", "owned_by": "anthropic",
         "router_unavailable_reason": "exhausted"},
        {"id": "glm-5.3", "owned_by": "z.ai", "router_unavailable_reason": reason}
    ]))
    .expect("deserialize catalog fixture");
    let warning = claude_unavailable_model_warning(Some("glm-5.3"), &models, None).unwrap();
    // The unservable opus-5-5 is never suggested; among servable rows the
    // opus family wins over a newer sonnet, and 4.1 beats a dated 4.0.
    assert!(warning.contains("`claude-opus-4-1`"), "{warning}");
    assert!(warning.contains("most capable"), "{warning}");

    let by_id = |id: &str| models.iter().find(|model| model.id == id).unwrap();
    assert_eq!(
        flagship_order(by_id("claude-opus-4-1"), by_id("claude-opus-4-20250514")),
        std::cmp::Ordering::Greater
    );
    assert_eq!(
        flagship_order(by_id("claude-sonnet-5-5"), by_id("claude-haiku-4-5")),
        std::cmp::Ordering::Greater
    );
}

#[test]
fn the_unavailable_model_warning_prefers_the_last_working_selection() {
    let models: Vec<RouterModel> = serde_json::from_value(json!([
        {"id": "claude-haiku-4-5", "owned_by": "anthropic"},
        {"id": "claude-opus-4-1", "owned_by": "anthropic"},
        {"id": "glm-5.3", "owned_by": "z.ai", "router_unavailable_reason": "exhausted"}
    ]))
    .expect("deserialize catalog fixture");
    let warning =
        claude_unavailable_model_warning(Some("glm-5.3"), &models, Some("claude-haiku-4-5\n"))
            .unwrap();
    assert!(warning.contains("`claude-haiku-4-5`"), "{warning}");
    assert!(warning.contains("last working"), "{warning}");
    let stale =
        claude_unavailable_model_warning(Some("glm-5.3"), &models, Some("glm-5.3")).unwrap();
    assert!(stale.contains("`claude-opus-4-1`"), "{stale}");

    // A servable launch records itself; the next exhausted launch uses it.
    let profile = tempfile::tempdir().unwrap();
    assert_eq!(
        claude_settings::claude_launch_model_warning(
            profile.path(),
            Some("claude-haiku-4-5"),
            &models
        ),
        None
    );
    let warning =
        claude_settings::claude_launch_model_warning(profile.path(), Some("glm-5.3"), &models)
            .unwrap();
    assert!(warning.contains("`claude-haiku-4-5`"), "{warning}");
}
